// === Tab: mySketch ===
let neurons = [];
let connections = [];
let numNeurons = 100;

function setup() {
  createCanvas(windowWidth, windowHeight);

  // 初期ニューロンを配置
  for (let i = 0; i < numNeurons; i++) {
    neurons.push(new Neuron(random(width), random(height)));
  }

  // 初期のニューロン間接続
  for (let i = 0; i < numNeurons; i++) {
    let neuron = neurons[i];
    for (let j = 0; j < numNeurons; j++) {
      if (i !== j && random() < 0.05) {
        connections.push(new Synapse(neuron, neurons[j]));
      }
    }
  }
}

function draw() {
  background(0);

  // 接続を描画
  for (let synapse of connections) {
    synapse.display();
  }

  // ニューロンを描画し、発火させる
  for (let neuron of neurons) {
    neuron.update();
    neuron.display();
  }

  // 発火のルーチン
  for (let neuron of neurons) {
    if (random() < 0.01) {
      neuron.fire();
    }
  }
}

// マウスがクリックされたときに新しいニューロンを追加
function mousePressed() {
  let newNeuron = new Neuron((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  neurons.push(newNeuron);

  // 新しいニューロンと既存のニューロンをランダムに接続
  for (let i = 0; i < neurons.length - 1; i++) {
    if (random() < 0.05) {
      connections.push(new Synapse(neurons[i], newNeuron));
    }
    if (random() < 0.05) {
      connections.push(new Synapse(newNeuron, neurons[i]));
    }
  }
}

// ニューロンのクラス
class Neuron {
  constructor(x, y) {
    this.position = createVector(x, y);
    this.fireRate = 0;  // 発火の強さ
    this.color = color(255, 0, 0);
  }

  // 発火を制御
  fire() {
    this.fireRate = 255; // 最大強度で発火
    setTimeout(() => {
      this.fireRate = 0; // 発火後、強度を元に戻す
    }, 100);
  }

  update() {
    // 発火中は周囲にシナプスを通じて信号を送る
    for (let synapse of connections) {
      if (synapse.inputNeuron === this && this.fireRate > 0) {
        synapse.transmit();
      }
    }
  }

  // ニューロンの描画
  display() {
    stroke(255);
    fill(this.color.levels[0], this.color.levels[1], this.color.levels[2], this.fireRate);
    ellipse(this.position.x, this.position.y, 20, 20);
  }
}

// シナプス（ニューロン間の接続）
class Synapse {
  constructor(inputNeuron, outputNeuron) {
    this.inputNeuron = inputNeuron;
    this.outputNeuron = outputNeuron;
    this.transmission = false;
    this.oscillator = null;
  }

  // 信号を伝達
  transmit() {
    if (!this.transmission) {
      this.transmission = true;

      // ランダムな周波数を生成（0.5 Hz ～ 30 Hz）
      let freq = random(0.5, 30);

      // 新しいオシレーターを生成
      this.oscillator = new p5.Oscillator('sine');
      this.oscillator.freq(freq);
      this.oscillator.amp(0.1);  // 音量の設定
      this.oscillator.start();
      this.oscillator.stop(0.1); // 0.1秒後に停止

      // 伝達が終わるまで少し待つ
      setTimeout(() => {
        this.transmission = false;
      }, 100);
    }
  }

  // シナプスの描画
  display() {
    if (this.transmission) {
      stroke(0, 255, 0, 150); // 信号が伝達中は緑色
    } else {
      stroke(255, 100); // 信号がないときは白
    }
    line(this.inputNeuron.position.x, this.inputNeuron.position.y,
         this.outputNeuron.position.x, this.outputNeuron.position.y);
  }
}

